import{_ as s,o as i,c as a,a3 as t}from"./chunks/framework.BwzYn71E.js";const g=JSON.parse('{"title":"Compression Algorithms for Implementing Idealized Systems","description":"","frontmatter":{"translationSource":{"title":"针对理想系统落地的压缩算法","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=ZllGoCkftlEvd5lMExXrO2","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/compression-algorithms-for-implementing-idealized-systems"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/compression-algorithms-for-implementing-idealized-systems"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/compression-algorithms-for-implementing-idealized-systems"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/compression-algorithms-for-implementing-idealized-systems"}]]},"headers":[],"relativePath":"compression-algorithms-for-implementing-idealized-systems.md","filePath":"logistics/src/page-ZllGoCkftlEvd5lMExXrO2.md"}'),o={name:"compression-algorithms-for-implementing-idealized-systems.md"};function l(n,e,r,p,c,d){return i(),a("div",null,[...e[0]||(e[0]=[t('<div class="logistics-content"><h1 id="compression-algorithms-for-implementing-idealized-systems" tabindex="-1">Compression Algorithms for Implementing Idealized Systems <a class="header-anchor" href="#compression-algorithms-for-implementing-idealized-systems" aria-label="Permalink to &quot;Compression Algorithms for Implementing Idealized Systems&quot;">​</a></h1><blockquote><p>Source page ID: <code>ZllGoCkftlEvd5lMExXrO2</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=ZllGoCkftlEvd5lMExXrO2" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><blockquote><p>Building lines with the human brain means using heuristic algorithms.</p><p>—恒星泰斗</p></blockquote><p><span id="source-block-wW6QHfP1USjLEMladjHekj"></span></p><h3 id="how-do-humans-lay-out-a-line" tabindex="-1">How Do Humans Lay Out a Line? <a class="header-anchor" href="#how-do-humans-lay-out-a-line" aria-label="Permalink to &quot;How Do Humans Lay Out a Line?&quot;">​</a></h3><p><span id="source-block-uaL3SZXJvWRi8tCAOsKjg9"></span></p><h4 id="taking-325-799-as-an-example" tabindex="-1">Taking 325/799 as an Example <a class="header-anchor" href="#taking-325-799-as-an-example" aria-label="Permalink to &quot;Taking 325/799 as an Example&quot;">​</a></h4><p><span id="source-block-kFyTivAiZwVCBBDDmZ3OQJ"></span></p><h5 id="draft" tabindex="-1">Draft <a class="header-anchor" href="#draft" aria-label="Permalink to &quot;Draft&quot;">​</a></h5><p>Without further ado, let us start with the TopoFlow graph. At the outset we usually get a messy graph:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-b26da58bb5f04a11.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="DdSBxHf2fCU3iPzs7yPfuW"><p>!? 325/799?!</p></div><p>In the first step we tidy up the graph so that its planarization “looks” relatively easy, for example like this:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-9e959ae217340ca1.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="TMveqqiN4IZUgY7ToSXerV"><p>325/799 after tidying</p></div><p>We can call such a rough layout a Draft. Looking at this Draft, we can see several features:</p><ol><li><p>Long chains of splitters appear (the main axis)</p></li><li><p>Recirculation convergers are distributed on both sides</p></li><li><p>Fairly suitable source and sink positions have been found</p></li><li><p>The wiring before the nodes looks fairly relaxed, with fewer crossings, and the connections at each node/main axis are fairly even</p></li></ol><p>The next step is to lay it out in the actual game according to the Draft.</p><p><span id="source-block-56Px6IMF9G9gnl3BSVCKDq"></span></p><h5 id="round-1" tabindex="-1">Round 1 <a class="header-anchor" href="#round-1" aria-label="Permalink to &quot;Round 1&quot;">​</a></h5><p>First, place the source and sink, as well as the components that connect directly to the source and sink:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-edd6d4d22e064b37.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="LqSjfxUrd0bWsxr2XDA6Zf"><p>step 1</p></div><p>Then consider the placement of the main chain:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c0e58cf38e27983c.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="SRq5GAHG4AiG9p8Zu6BuU8"><p>step 2</p></div><p>To make layout easier, we split apart the three-way merge on the lower side (the flow was verified to remain unchanged), giving:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-ff889173e26b66d9.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="76ar2gsl1y8wNqCRPleDBG"><p>step 3.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-2c152ddcb9542bce.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="jwCzlI8G1gycgxqNyT2l6w"><p>step 3.2</p></div><p>We continue splitting the lower three-way merge:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-9f8db3e6ea188340.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="3xEMQlKU5Y2tTygkPi5IO5"><p>step 4.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-6694e35523aed094.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="ciPPIHvGx6qDWHfEi6vgSN"><p>step 4.2</p></div><p>An important observation here: a component&#39;s orientation can be changed dynamically while connecting belts—that is, a component should not have an “orientation” attribute to begin with</p><p>Then lay out the upper-side merging unit:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-aa304f3647f6ffeb.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="qhJmout6Jgi8W97nJ219cz"><p>step 5</p></div><p>Continue laying out:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-81adb66e7f074d5d.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="0VekmVzjrBjDbEUYn7Q07n"><p>step 6.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-796819c117d7fa9d.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="yurtIy4ealBxnxe0TNL6vQ"><p>step 6.2</p></div><p>At this point we found that the connection from the lower-left converger → upper-right converger could no longer be established, so we modified the layout:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-74af56a032e69980.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="hyBjG3YMQ4G9hwKyRMZFCB"><p>step 7.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-314f4c058d985449.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="HZfOj6mEyi8gk6KGkS04bY"><p>step 7.2</p></div><p>Then complete the final connections:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-55b86b0962b61116.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="lkguqyYn4PjZQedkl0fpeg"><p>step 8</p></div><p>So we obtained the first feasible layout (area 110, 34 components; after flow simulation, the periodic flow is indeed 325/799)</p><p><span id="source-block-trnc79pKkAzcvat5lLwPk4"></span></p><h5 id="round-2" tabindex="-1">Round 2 <a class="header-anchor" href="#round-2" aria-label="Permalink to &quot;Round 2&quot;">​</a></h5><p>Obviously the result of the first round looks ugly, so we consider rolling back and re-laying out the upper side:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-5cb8abd6b0d33c7c.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="gCtHP9Ii5zAjWJXjxXtlTR"><p>step 1</p></div><p>Continue:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-0b51f713ecc097dc.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="M3yqNmUq37TqEWB8T4JoLB"><p>step 2</p></div><p>Space on the upper side is tight, so we consider modifying the graph:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-3348f44656e3e6fa.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="VfRaDArr8CfUVcoNSNo4Xe"><p>step 3.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-abc81101899179b5.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="MTzRT8j69JFR2h3PxUkJSc"><p>step 3.2</p></div><p>Continue:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-8caea85c91e316b2.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="5F9xN7hbpeMQOW823RLI7s"><p>step 4</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-04e7961f2ab79336.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="I29O44Z0BA0H8ErrNDqLN6"><p>step 5</p></div><p>The second feasible layout (area 99, 31 components; after flow simulation, the periodic flow is indeed 325/799)</p><p><span id="source-block-W3WqdXD4YJV2s5YwNQy4Rv"></span></p><h5 id="round-3" tabindex="-1">Round 3 <a class="header-anchor" href="#round-3" aria-label="Permalink to &quot;Round 3&quot;">​</a></h5><p>Roll back the upper side:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-cbdbdfe32553503b.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="Ke1GSBELTSu8dhMHKBWVcp"><p>step 1</p></div><p>Split the converger:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-3ee61b72412b1958.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="3dLtm8HZ35Edwsmuvr0BHZ"><p>step 2.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-84f3a8a6d9213725.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="NfQKc3CrCMXzXRE1N1KATU"><p>step 2.2</p></div><p>Finally, polish it a little:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-ef9d7525a6a8eae2.png" alt="Compression Algorithms for Implementing Idealized Systems"></p><div class="logistics-image-caption" data-source-block="AWb554q2yv7aMNachZbUlZ"><p>step 3</p></div><p>This gives a fairly decent overall layout (area 88, 32 components; after flow simulation, the periodic flow is indeed 325/799)</p><p><span id="source-block-Gu3I2yf3UWCp38vwbOqzfU"></span></p><h4 id="what-operations-did-we-perform-along-the-way" tabindex="-1">What Operations Did We Perform Along the Way? <a class="header-anchor" href="#what-operations-did-we-perform-along-the-way" aria-label="Permalink to &quot;What Operations Did We Perform Along the Way?&quot;">​</a></h4><p>First, through “intuition” and “experience” we designed a Draft that “looks good”;</p><p>Second, we essentially used only the following three operations (of course, there were also some local fixes and rollbacks)</p><ol><li><p><strong>Modify the topology</strong>: split and merge nodes in the TopoFlow graph while keeping the flow unchanged;</p></li><li><p><strong>Place components</strong>: guided by the Draft, look for suitable positions at which to place components/main axes</p></li><li><p><strong>Connect belts</strong>: connect the components that have already been placed</p></li></ol><p>and the final blueprint is obtained;</p><p>It is worth noting that <strong>almost every one of our operations is based on the result of the previous one</strong>, and the whole layout process <strong>grows like a tree</strong> (this may also be why randomized/genetic algorithms are less efficient—after all, our pruning is more aggressive);</p><p><span id="source-block-NBrxgFGLhOL6s39emZ5HFt"></span></p><h3 id="translating-these-processes-into-a-search-strategy-that-guides-heuristic-search" tabindex="-1">Translating These Processes into a Search Strategy That Guides Heuristic Search <a class="header-anchor" href="#translating-these-processes-into-a-search-strategy-that-guides-heuristic-search" aria-label="Permalink to &quot;Translating These Processes into a Search Strategy That Guides Heuristic Search&quot;">​</a></h3><p><span id="source-block-2M9WwkN54ZkkJuQHQK4oxZ"></span></p><h4 id="draft-generation" tabindex="-1">Draft Generation <a class="header-anchor" href="#draft-generation" aria-label="Permalink to &quot;Draft Generation&quot;">​</a></h4><p>A Draft is a compact template generated from a topological ordering.</p><p><span id="source-block-unCgOMXaO5XmPoCIoZHHA2"></span></p><h5 id="main-axis-discovery" tabindex="-1">Main Axis Discovery <a class="header-anchor" href="#main-axis-discovery" aria-label="Permalink to &quot;Main Axis Discovery&quot;">​</a></h5><p>The main axis has the following generation paths:</p><ol><li><p>Starting from the successor relation of splitters, enumerate directed simple paths</p></li><li><p>Starting from the “allowed to make direct contact” successor relation (avoiding splitter → converger priority), enumerate contact chains</p></li></ol><p><span id="source-block-SMYQR2ywrfNO72ZlgS4WAj"></span></p><h5 id="recirculation-allocation" tabindex="-1">Recirculation Allocation <a class="header-anchor" href="#recirculation-allocation" aria-label="Permalink to &quot;Recirculation Allocation&quot;">​</a></h5></div>',1)])])}const h=s(o,[["render",l]]);export{g as __pageData,h as default};
